refentry.refsect1:
  &reftitle.examples;

   Exemple avec Yar_Server::handle


<?php
class API {
    /**
     * Le bloc de documentation est affiché sur la page d'informations du service.
     * @param string $parameter
     * @return string
     */
    public function some_method($parameter, $option = "foo") {
        return "some_method";
    }

    protected function client_can_not_see() {
    }
}

$service = new Yar_Server(new API());
$service->handle();
?>




   Personnalisation de la page d'informations du service avec
   __info (à partir de Yar 2.3.0)


<?php
class API {
    public function some_method($parameter, $option = "foo") {
        return "some_method";
    }

    /*
     * Doit être protected. Cette méthode est appelée sur les requêtes GET avec
     * le balisage de la page que Yar aurait autrement produite, et la chaîne
     * qu'elle retourne est envoyée au client à la place.
     */
    protected function __info($markup) {
        return "Hello world";
    }
}

$service = new Yar_Server(new API());
$service->handle();
?>
